import type { Row } from './model';
import { createSettingsLaneOwner, scopedSettingsPath, settingsObject, type SettingsRequest } from './settings-protocol';
import { collectionValuesEqual, collectionWriteRejected } from './settings-collection-value';

type Property = { key: string; node: Node; leading: string };
type Node = { start: number; end: number; value: unknown; properties?: Property[]; comma?: number; empty?: boolean };
/** JSONC syntax/offset reader. Comments and whitespace are never regenerated by edits. */
function document(source: string): Node {
  let at = source.startsWith('\uFEFF') ? 1 : 0, depth = 0;
  const invalid = (): never => { throw new Error('Invalid JSONC configuration'); };
  function space() {
    while (at < source.length) {
      if (/\s/.test(source[at])) { at++; continue; }
      if (source.startsWith('//', at)) { at += 2; while (at < source.length && source[at] !== '\n' && source[at] !== '\r') at++; continue; }
      if (source.startsWith('/*', at)) { const end = source.indexOf('*/', at + 2); if (end < 0) invalid(); at = end + 2; continue; }
      break;
    }
  }
  function string(): string {
    const start = at++;
    while (at < source.length) {
      const character = source[at++];
      if (character === '\\') { at++; continue; }
      if (character === '"') return JSON.parse(source.slice(start, at));
    }
    return invalid();
  }
  function read(): Node {
    space(); if (++depth > 512) invalid();
    const start = at, character = source[at];
    let value: unknown, properties: Property[] | undefined, comma: number | undefined;
    if (character === '{' || character === '[') {
      at++; let leadingStart = at; space();
      const object = character === '{', end = object ? '}' : ']';
      const entries: [string, unknown][] = [], array: unknown[] = [];
      if (object) properties = [];
      while (source[at] !== end) {
        let key = ''; const keyStart = at;
        if (object) { if (source[at] !== '"') invalid(); key = string(); space(); if (source[at++] !== ':') invalid(); }
        const node = read();
        if (object) { properties!.push({ key, node, leading: source.slice(leadingStart, keyStart) }); entries.push([key, node.value]); }
        else array.push(node.value);
        space();
        if (source[at] !== ',') { if (source[at] !== end) invalid(); break; }
        comma = at++; leadingStart = at; space();
        if (source[at] !== end) comma = undefined;
      }
      if (source[at++] !== end) invalid();
      value = object ? Object.fromEntries(entries) : array;
    } else if (character === '"') value = string();
    else {
      const match = source.slice(at).match(/^(?:true|false|null|-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?)/);
      if (!match) invalid();
      at += match![0].length; value = JSON.parse(match![0]);
    }
    depth--; return { start, end: at, value, properties, comma };
  }
  space();
  if (at === source.length) return { start: at, end: at, value: {}, properties: [], empty: true };
  const node = read(); space(); if (at !== source.length) invalid(); return node;
}
const property = (node: Node, key: string) => node.properties?.filter(property => property.key === key).at(-1)?.node;
export function parseCollectionJSONC(source: string): Row { return settingsObject(document(source).value); }
export function collectionJSONCEntry(source: string, section: string, name: string): { value: Row; raw: string; leading: string } {
  const root = document(source), parent = property(root, section), entry = parent && property(parent, name);
  if (!entry) throw new Error('Configuration definition not found');
  return { value: settingsObject(entry.value), raw: source.slice(entry.start, entry.end), leading: parent?.properties?.filter(property => property.key === name).at(-1)?.leading || '' };
}
function insert(source: string, node: Node, key: string, raw: string, leading = ''): string {
  if (!node.properties) throw new Error('Configuration section must be an object');
  if (node.empty) return `${source}${source && !/[\r\n]$/.test(source) ? '\n' : ''}{${leading}${JSON.stringify(key)}: ${raw}}\n`;
  const count = node.properties.length;
  const content = `${count && node.comma === undefined ? ',' : ''}${leading || '\n'}${JSON.stringify(key)}: ${raw}\n`;
  const offset = node.end - 1;
  return source.slice(0, offset) + content + source.slice(offset);
}
function patchObject(source: string, patch: Row): string {
  let result = source;
  for (const [key, value] of Object.entries(patch)) {
    if (value === undefined) continue;
    const root = document(result), existing = property(root, key), raw = JSON.stringify(value);
    result = existing ? result.slice(0, existing.start) + raw + result.slice(existing.end) : insert(result, root, key, raw);
  }
  return result;
}
export function collectionJSONCInsert(source: string, section: string, name: string, raw: string, patch: Row = {}, leading = ''): string {
  const root = document(source), parent = property(root, section);
  if (parent && property(parent, name)) throw new Error('Configuration definition already exists');
  const entry = patchObject(raw, patch);
  const result = parent ? insert(source, parent, name, entry, leading) : insert(source, root, section, `{${leading}${JSON.stringify(name)}:${entry}}`);
  parseCollectionJSONC(result); return result;
}

export type CollectionJSONCSource = { path: string; directory?: string; scope: string; section: 'command' | 'agent'; name: string; raw: string; global?: boolean; destination?: { path: string; global?: boolean; allowMissing?: boolean } };
type CopyPhase = 'draft' | 'unknown' | 'confirmed' | 'done';
/** The original document stays intact. After dispatch, retries can only read the captured target. */
export function createCollectionJSONCCopy(source: CollectionJSONCSource, send: SettingsRequest, current: () => boolean) {
  const transport = createSettingsLaneOwner(send, current);
  let phase: CopyPhase = 'draft', busy = false, receipt: { name: string; config: Row } | undefined;
  const destination = source.destination ?? (source.global || source.scope === 'user' ? { path: '', global: true } : source);
  const file = scopedSettingsPath(`/api/fs/read?path=${encodeURIComponent(destination.path)}`, source.directory);
  async function save(name: string, patch: Row) {
    const lane = transport.capture(); if (!lane?.current()) throw new Error('Runtime changed');
    if (busy) throw new Error('Configuration copy pending'); if (phase === 'done') return;
    busy = true;
    const check = () => { if (!lane.current()) throw new Error('Runtime changed'); };
    const read = async () => {
      let value: unknown;
      try { value = await lane.request(destination.global ? '/api/config/global/opencode' : file, 'GET'); }
      catch (error) { check(); if (phase === 'draft' && source.destination?.allowMissing && error && typeof error === 'object' && 'status' in error && error.status === 404) return '{}'; throw error; }
      check();
      const text = destination.global ? settingsObject(value).content : value;
      if (typeof text !== 'string') throw new Error('Invalid configuration source'); return text;
    };
    try {
      if (phase === 'draft') {
        if (!name.trim()) throw new Error('Definition name required');
        const metadata = settingsObject(await lane.request(scopedSettingsPath(`/api/config/${source.section === 'command' ? 'commands' : 'agents'}/${encodeURIComponent(name)}`, source.directory), 'GET')); check();
        const sources = settingsObject(metadata.sources), md = settingsObject(sources.md), json = settingsObject(sources.json);
        if (typeof md.exists !== 'boolean' || typeof json.exists !== 'boolean') throw new Error('Invalid definition source authority');
        if (md.exists || json.exists) throw new Error('Configuration definition already exists');
        const latest = await read(), entry = collectionJSONCEntry(source.raw, source.section, source.name);
        const text = collectionJSONCInsert(latest, source.section, name, entry.raw, patch, entry.leading);
        receipt = { name, config: collectionJSONCEntry(text, source.section, name).value };
        check(); phase = 'unknown';
        let response: unknown;
        try { response = await lane.request(destination.global ? '/api/config/global/opencode' : scopedSettingsPath('/api/fs/write', source.directory), destination.global ? 'PUT' : 'POST', destination.global ? { content: text } : { path: destination.path, content: text }); }
        catch (error) { if (collectionWriteRejected(error)) { phase = 'draft'; receipt = undefined; } throw error; }
        if (response != null && response !== true) settingsObject(response);
        phase = 'confirmed'; check();
      }
      const text = await read();
      if (!receipt || !collectionValuesEqual(collectionJSONCEntry(text, source.section, receipt.name).value, receipt.config)) throw new Error('Copied definition is not confirmed');
      phase = 'done';
    } finally { busy = false; }
  }
  return { save, phase: () => phase, replaceLane: transport.replaceLane };
}
